<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Laporan anggota';$filter=isset($_GET['status'])?(string)$_GET['status']:'';$allowed=['baru','diproses','selesai','ditolak'];$sql='SELECT l.*,a.nama AS anggota_nama,a.kelas,k.nama AS kategori FROM laporan l JOIN anggota a ON a.id=l.anggota_id LEFT JOIN kategori_laporan k ON k.id=l.kategori_id';$params=[];if(in_array($filter,$allowed,true)){$sql.=' WHERE l.status=?';$params[]=$filter;}$sql.=' ORDER BY FIELD(l.status,\'baru\',\'diproses\',\'selesai\',\'ditolak\'),l.created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$items=$stmt->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Tinjau aspirasi anggota, ubah status, dan berikan tanggapan.</p><form class="filter-form" method="get"><label class="sr-only" for="status-filter">Filter status</label><select id="status-filter" name="status"><option value="">Semua status</option><?php foreach($allowed as $status):?><option value="<?=osis_e($status)?>" <?=$filter===$status?'selected':''?>><?=osis_e(ucfirst($status))?></option><?php endforeach;?></select><button class="button button-outline button-small" type="submit">Filter</button></form></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Laporan</th><th>Anggota</th><th>Kategori</th><th>Dikirim</th><th>Status</th><th></th></tr></thead><tbody><?php if($items):foreach($items as $item):?><tr><td><strong><?=osis_e($item['judul'])?></strong><small class="table-subtext"><?=osis_e(mb_strimwidth(strip_tags($item['isi']),0,90,'…','UTF-8'))?></small></td><td><?=osis_e($item['anggota_nama'])?><small class="table-subtext"><?=osis_e($item['kelas']?:'')?></small></td><td><?=osis_e($item['kategori']?:'—')?></td><td><?=osis_e(osis_format_date($item['created_at'],true))?></td><td><span class="badge badge-status badge-<?=osis_e($item['status'])?>"><?=osis_e(ucfirst($item['status']))?></span></td><td><a class="table-action" href="<?=osis_e(osis_url('admin/laporan/detail.php?id='.(int)$item['id']))?>">Buka ↗</a></td></tr><?php endforeach;else:?><tr><td colspan="6" class="empty-inline">Tidak ada laporan untuk filter ini.</td></tr><?php endif;?></tbody></table></div></div>
<?php osis_admin_page_end(); ?>
